<script lang="ts">
 import ShortsShelf from './ShortsShelf.svelte';
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {page} from '$app/state';import {Button} from '$lib/components/ui/button';import {Input} from '$lib/components/ui/input';import {Film,Bookmark,History,Search} from '@lucide/svelte';import {request} from '../api';import VideoCard from './VideoCard.svelte';import {appendUnique,requestGate} from './feed-state';
 const gate=requestGate();
 let {following=false,library='',user}:{following?:boolean;library?:string;user:any}=$props();let shorts=$state<any[]>([]);let videos=$state<any[]>([]),cursor=$state(''),loading=$state(true),busy=$state(false),error=$state(''),query=$state(page.url.searchParams.get('q')||'');
 const heading=$derived(library==='saved'?'Saved videos':library==='history'?'Watch history':following?'Following':page.url.pathname==='/search'?'Search videos':'Discover');
 onMount(()=>{void load();return()=>{gate.next();};});async function load(more=false){const sequence=gate.next();if(more)busy=true;else loading=true;error='';try{if(library){const result=await request(`/viewer/${library}${more&&cursor?'?cursor='+encodeURIComponent(cursor):''}`);if(!gate.current(sequence))return;videos=more?appendUnique(videos,result.items):result.items;cursor=result.next_cursor||'';}else{const params=new URLSearchParams({format:'standard',...(following?{filter:'following'}:{}),...(page.url.searchParams.get('q')?{q:page.url.searchParams.get('q')!}:{}),...(more&&cursor?{cursor}:{})});const result=await request(`/feed?${params}`);if(!gate.current(sequence))return;videos=more?appendUnique(videos,result.items):result.items;cursor=result.next_cursor||'';}if(!more&&!library&&!following&&!query){const shelf=await request('/feed?format=short').catch(()=>({items:[]}));if(gate.current(sequence))shorts=shelf.items||[];}}catch(e){if(gate.current(sequence))error=(e as Error).message;}finally{if(gate.current(sequence)){loading=false;busy=false;}}}
</script>
{#if !library&&!following&&page.url.pathname!=='/search'&&videos.length>0}<h1 class="sr-only">{heading}</h1>{/if}
<div class="browse-heading" class:browse-quiet={!library&&!following&&page.url.pathname!=='/search'&&videos.length>0}><div><h1>{heading}</h1><p>{library?'Your personal viewing library.':following?'The latest public videos from creators you follow.':'Stories, ideas, and creators worth watching.'}</p></div>{#if user&&!library}<a class="browse-library" href="/library"><Bookmark class="size-4"/>Your library</a>{/if}</div>
{#if !library&&page.url.pathname==='/search'}<form role="search" class="browse-search" onsubmit={e=>{e.preventDefault();void goto(`/search?q=${encodeURIComponent(query.trim())}`);}}><label class="sr-only" for="browse-query">Search public videos</label><Input id="browse-query" type="search" bind:value={query} placeholder="Search videos"/><Button variant="outline" type="submit"><Search class="size-4"/><span class="sr-only">Search</span></Button></form>{:else if library}<nav class="library-tabs" aria-label="Library"><a href="/library" aria-current={library==='saved'?'page':undefined}><Bookmark class="size-4"/>Saved</a><a href="/history" aria-current={library==='history'?'page':undefined}><History class="size-4"/>History</a><a href="/settings/privacy">Manage history</a></nav>{/if}
{#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" onclick={()=>load()}>Try again</Button></div>{/if}
{#if !library&&page.url.pathname!=='/search'}<nav class="browse-formats" aria-label="Browse formats"><a href="/discover" aria-current={!following?'page':undefined}>Videos</a><a href="/shorts">Shorts</a><a href="/following" aria-current={following?'page':undefined}>Following</a></nav>{/if}
{#if loading}<div class="browse-grid" aria-label="Loading videos" role="status">{#each Array(6) as _}<div class="video-skeleton"><div></div><span></span><small></small></div>{/each}</div>{:else if videos.length}<div class="browse-grid">{#each videos.slice(0,6) as video(video.id)}<VideoCard {video}/>{/each}</div><ShortsShelf videos={shorts}/>{#if videos.length>6}<div class="browse-grid">{#each videos.slice(6) as video(video.id)}<VideoCard {video}/>{/each}</div>{/if}{#if cursor}<div class="browse-more"><Button variant="outline" disabled={busy} onclick={()=>load(true)}>{busy?'Loading…':'Show more videos'}</Button></div>{/if}{:else if !error}<div class="browse-empty"><Film class="size-9"/><h2>{query?'No videos match your search':library==='saved'?'Keep something for later':library==='history'?'Your watch history starts here':following?'Your following feed is quiet':'The first stories are on their way'}</h2><p>{query?'Try a different title or topic.':library==='saved'?'Save videos while watching to find them here.':following?'Visit a creator profile and follow them for new releases.':'Browse Shorts, explore a creator, or make a video of your own.'}</p><div><Button variant="outline" href="/shorts">Explore Shorts</Button>{#if user&&!library}<Button variant="ghost" href="/studio">Open Studio</Button>{:else}<Button variant="ghost" href={library||following||query?'/discover':'/templates'}>{library||following||query?'Discover videos':'Explore templates'}</Button>{/if}</div></div><ShortsShelf videos={shorts}/>{/if}
<style>.browse-formats a:focus-visible,.library-tabs a:focus-visible{outline:2px solid var(--ring);outline-offset:3px}.browse-formats a{min-height:44px;display:flex;align-items:center}.library-tabs{flex-wrap:wrap}.browse-quiet{display:none!important}.browse-formats{display:flex;gap:9px;margin-bottom:24px}.browse-formats a{padding:9px 15px;background:var(--muted);border-radius:8px;font-size:12px;font-weight:500}.browse-formats a[aria-current=page]{background:var(--foreground);color:var(--background)}.browse-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:26px}.browse-heading h1{font-size:26px;font-weight:600;letter-spacing:-.02em}.browse-heading p{font-size:13px;color:var(--muted-foreground);line-height:1.7;margin-top:8px}.browse-library{display:flex;align-items:center;gap:8px;font-size:12px;white-space:nowrap;color:var(--muted-foreground)}.browse-search{display:flex;gap:10px;max-width:560px;margin-bottom:30px}.browse-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px 22px}.browse-more{text-align:center;padding:32px}.browse-empty{display:flex;align-items:center;flex-direction:column;text-align:center;gap:16px;padding:36px 20px;max-width:520px;margin:auto}.browse-empty h2{font-size:20px;font-weight:550}.browse-empty p{font-size:13px;line-height:1.8;color:var(--muted-foreground)}.browse-empty>div{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}.video-skeleton>div{aspect-ratio:16/9;background:var(--muted);border-radius:10px}.video-skeleton span,.video-skeleton small{display:block;background:var(--muted);height:12px;width:70%;border-radius:3px;margin-top:14px}.video-skeleton small{width:40%;height:10px}.library-tabs{display:flex;gap:24px;align-items:center;margin:0 0 28px;font-size:13px}.library-tabs a{display:flex;align-items:center;gap:8px;padding:12px 0;color:var(--muted-foreground)}.library-tabs a[aria-current=page]{color:var(--foreground);font-weight:600}@media(min-width:1500px){.browse-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:900px){.browse-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.browse-grid{grid-template-columns:1fr;gap:28px}.browse-heading{align-items:flex-start}.browse-heading h1{font-size:24px}.browse-library{font-size:0}.browse-library :global(svg){width:20px;height:20px}.browse-empty{padding:20px 0;gap:12px}.browse-empty>:global(svg){display:none}.library-tabs{gap:15px;font-size:12px}}
</style>
